import json
G=[[0]*19 for _ in range(17)]
for r,c in [(3,4),(8,11),(13,6)]:
 for j in range(c-2,c+3):
  if 0<=r-2<17 and 0<=j<19:G[r-2][j]=5
 for rr in [r-1,r,r+1]:
  if 0<=rr<17:
   for j in [c-2,c+2]:
    if 0<=j<19:G[rr][j]=2
   if rr==r-1 and 0<=c<19:G[rr][c]=5
   if rr==r and 0<=c<19:G[rr][c]=3
 if 0<=r+2<17:
  G[r+2]=[2]*19
  for j in range(c-2,c+3):
   if 0<=j<19:G[r+2][j]=8
print([len(x) for x in G]); print(json.dumps(G,separators=(',',':')))
